<?php
namespace App\Services;
use App\Models\{BookingServis,DetailServis,Servis,ServisSparepart,Transaksi,JenisServis,KendaraanPelanggan}; use Illuminate\Support\Facades\DB; use RuntimeException;
class ServisService {
 private function code():string { do {$c='SRV-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));} while(Servis::where('kode_servis',$c)->exists()); return $c; }
 private function transactionCode():string { do {$c='TRX-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));} while(Transaksi::where('kode_transaksi',$c)->exists()); return $c; }
 public function createFromBooking(int $bookingId,int $petugasId,?int $kilometer,?string $catatan,?int $advisorId=null,bool $explicitAssignment=false):Servis { return DB::transaction(function()use($bookingId,$petugasId,$kilometer,$catatan,$advisorId,$explicitAssignment){ app(WorkOrderAuthorizationService::class)->assertCurrentActor(null, 'manage'); $b=BookingServis::lockForUpdate()->findOrFail($bookingId); $existing=Servis::where('id_booking_servis',$b->id_booking_servis)->first(); if($existing) return $existing->fresh(['bookingServis','pelanggan','kendaraan','petugas','serviceAdvisor']); if($b->status!=='diterima') throw new RuntimeException('Booking servis harus berstatus diterima.'); if($explicitAssignment)app(\App\Services\ServicePersonnelAvailabilityService::class)->eligible($petugasId,$b->tanggal->toDateString(),substr((string)$b->jam,0,5),(int)$b->id_jenis_servis); if($advisorId){$advisor=\App\Models\ServiceStaffProfile::where('id_petugas',$advisorId)->where('can_be_service_advisor',true)->whereHas('petugas',fn($q)=>$q->where('status','aktif'))->exists();if(!$advisor)throw new RuntimeException('Service advisor tidak eligible.');} $v=KendaraanPelanggan::where('id_kendaraan_pelanggan',$b->id_kendaraan_pelanggan)->where('id_pelanggan',$b->id_pelanggan)->lockForUpdate()->firstOrFail(); $km=$kilometer ?? (int)($v->kilometer??0); if($km<0 || ($v->kilometer!==null && $km<(int)$v->kilometer) ) throw new RuntimeException('Kilometer tidak boleh lebih kecil dari kilometer kendaraan.'); $s=new Servis(); $s->forceFill(['kode_servis'=>$this->code(),'id_booking_servis'=>$b->id_booking_servis,'id_pelanggan'=>$b->id_pelanggan,'id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'id_petugas'=>$petugasId,'id_service_advisor'=>$advisorId,'kilometer'=>$km,'keluhan'=>$b->keluhan,'catatan'=>$catatan ?: $b->catatan,'status'=>'pemeriksaan','biaya_jasa'=>0,'biaya_sparepart'=>0,'total_biaya'=>0]); $s->save(); $b->forceFill(['status'=>'diproses'])->save(); if($b->id_jenis_servis && $b->jenisServis){ $initDetail = new DetailServis(); $initDetail->forceFill(['id_servis'=>$s->id_servis,'id_jenis_servis'=>$b->id_jenis_servis,'deskripsi_pekerjaan'=>$b->jenisServis->nama_servis,'biaya'=>(float)($b->jenisServis->estimasi_harga ?? 0),'catatan'=>'Layanan awal sesuai reservasi booking'])->save(); } if($v->kilometer===null || $km>(int)$v->kilometer){$v->forceFill(['kilometer'=>$km])->save();} app(ServiceExecutionService::class)->recordEvent($s->id_servis,'check_in','Kendaraan check-in untuk Work Order','petugas',$petugasId); app(ServiceNotificationService::class)->forService($s->fresh('pelanggan'),'Kendaraan mulai diperiksa','Kendaraan Anda sudah masuk tahap pemeriksaan dengan work order '.$s->kode_servis.'.'); return $s; }); }
 public function updateInspection(int $id,string $diagnosis,?string $note):Servis { return DB::transaction(function()use($id,$diagnosis,$note){$s=Servis::lockForUpdate()->findOrFail($id);app(WorkOrderAuthorizationService::class)->assertCurrentActor($s);if($s->status!=='pemeriksaan')throw new RuntimeException('Pemeriksaan hanya dapat diisi pada status pemeriksaan.');app(InspectionIntegrityService::class)->invalidate($s,'Diagnosis berubah');$s->forceFill(['hasil_pemeriksaan'=>$diagnosis,'catatan'=>$note??$s->catatan,'status'=>'dikerjakan'])->save();app(ServiceExecutionService::class)->recordEvent($s->id_servis,'inspection_completed','Pemeriksaan selesai','petugas',$s->id_petugas);app(ServiceNotificationService::class)->forService($s->fresh('pelanggan'),'Servis mulai dikerjakan','Pemeriksaan selesai. Tim teknisi mulai mengerjakan kendaraan Anda.');return $s;}); }
 public function addDetail(int $id,?int $jenis,string $description,string $cost,?string $note):DetailServis { return DB::transaction(function()use($id,$jenis,$description,$cost,$note){$s=Servis::lockForUpdate()->findOrFail($id);app(WorkOrderAuthorizationService::class)->assertCurrentActor($s);if($s->status!=='dikerjakan'||$s->id_transaksi!==null)throw new RuntimeException('Detail pekerjaan hanya dapat ditambahkan saat servis dikerjakan.');if($jenis!==null)JenisServis::where('status','aktif')->findOrFail($jenis);if(trim($description)===''||(float)$cost<0)throw new RuntimeException('Detail pekerjaan atau biaya tidak valid.');app(InspectionIntegrityService::class)->invalidate($s,'Jasa berubah');$d=new DetailServis();$d->forceFill(['id_servis'=>$s->id_servis,'id_jenis_servis'=>$jenis,'deskripsi_pekerjaan'=>trim($description),'biaya'=>$cost,'catatan'=>$note])->save();return $d;}); }
 public function removeDetail(int $serviceId,int $detailId):void { DB::transaction(function()use($serviceId,$detailId){$s=Servis::lockForUpdate()->findOrFail($serviceId);app(WorkOrderAuthorizationService::class)->assertCurrentActor($s);if($s->status!=='dikerjakan'||$s->id_transaksi!==null)throw new RuntimeException('Detail tidak dapat dihapus pada status servis ini.');DetailServis::where('id_servis',$s->id_servis)->whereKey($detailId)->firstOrFail()->delete();app(InspectionIntegrityService::class)->invalidate($s,'Jasa dihapus');}); }
 public function finalizeService(int $serviceId,int $petugasId,?callable $beforeCommit=null):Transaksi { return DB::transaction(function()use($serviceId,$petugasId,$beforeCommit){$s=Servis::lockForUpdate()->findOrFail($serviceId);app(WorkOrderAuthorizationService::class)->assertCurrentActor($s, 'manage');if($s->status!=='dikerjakan'||$s->id_transaksi!==null)throw new RuntimeException('Servis tidak siap difinalisasi atau sudah memiliki tagihan.');app(ServiceExecutionService::class)->assertCanFinalize($s->id_servis);$items=ServisSparepart::where('id_servis',$s->id_servis)->orderBy('id_sparepart')->get();$jasa=(string)DB::selectOne('SELECT CAST(COALESCE(SUM(biaya),0) AS DECIMAL(15,2)) AS value FROM detail_servis WHERE id_servis=?',[$s->id_servis])->value;$spare=(string)DB::selectOne('SELECT CAST(COALESCE(SUM(subtotal),0) AS DECIMAL(15,2)) AS value FROM servis_sparepart WHERE id_servis=?',[$s->id_servis])->value;$total=(string)DB::selectOne('SELECT CAST(CAST(? AS DECIMAL(15,2)) + CAST(? AS DECIMAL(15,2)) AS DECIMAL(15,2)) AS value',[$jasa,$spare])->value;$txCode=$this->transactionCode();$inventory=app(InventoryService::class);$inventory->consumeServicePartsWithinTransaction($items,$petugasId,$s->id_servis,$s->kode_servis);if($beforeCommit)$beforeCommit();$tx=new Transaksi();$tx->forceFill(['kode_transaksi'=>$txCode,'id_pelanggan'=>$s->id_pelanggan,'id_petugas'=>$petugasId,'jenis_transaksi'=>'servis','tanggal'=>now(),'subtotal'=>$total,'diskon'=>0,'total'=>$total,'status'=>'belum_bayar','catatan'=>'Tagihan '.$s->kode_servis]);$tx->save();$s->forceFill(['biaya_jasa'=>$jasa,'biaya_sparepart'=>$spare,'total_biaya'=>$total,'id_transaksi'=>$tx->id_transaksi])->save();app(ServiceExecutionService::class)->recordEvent($s->id_servis,'finalized','Work Order difinalisasi','petugas',$petugasId);return $tx;}); }
 public function finalizeWithPromo(int $serviceId,int $petugasId,?int $promoId=null):Transaksi{return DB::transaction(function()use($serviceId,$petugasId,$promoId){$tx=$this->finalizeService($serviceId,$petugasId);$effectivePromoId=$promoId ?? Servis::with('bookingServis')->find($serviceId)?->bookingServis?->id_promo;if($effectivePromoId!==null){try{app(PromoEngineService::class)->applyToTransaction($tx,(int)$effectivePromoId,'servis');}catch(RuntimeException $e){if($promoId!==null)throw $e;}}return$tx->fresh();});}
 public function finalizeFromQc(int $serviceId,int $petugasId):Transaksi { return DB::transaction(function()use($serviceId,$petugasId){ $s=Servis::with('bookingServis')->lockForUpdate()->findOrFail($serviceId); if($s->id_transaksi){ return Transaksi::findOrFail($s->id_transaksi); } $user=auth()->user(); if($user){ abort_unless($user->roleKey()==='super_admin' || $user->hasPermission('qc.manage') || $user->hasPermission('finance.verify') || $user->hasPermission('service.manage'), 403); } if($s->status!=='dikerjakan') throw new RuntimeException('Servis tidak siap difinalisasi.'); app(ServiceExecutionService::class)->assertCanFinalize($s->id_servis); $items=ServisSparepart::where('id_servis',$s->id_servis)->orderBy('id_sparepart')->get(); $jasa=(string)DB::selectOne('SELECT CAST(COALESCE(SUM(biaya),0) AS DECIMAL(15,2)) AS value FROM detail_servis WHERE id_servis=?',[$s->id_servis])->value; $spare=(string)DB::selectOne('SELECT CAST(COALESCE(SUM(subtotal),0) AS DECIMAL(15,2)) AS value FROM servis_sparepart WHERE id_servis=?',[$s->id_servis])->value; $total=(string)DB::selectOne('SELECT CAST(CAST(? AS DECIMAL(15,2)) + CAST(? AS DECIMAL(15,2)) AS DECIMAL(15,2)) AS value',[$jasa,$spare])->value; $txCode=$this->transactionCode(); $inventory=app(InventoryService::class); $inventory->consumeServicePartsWithinTransaction($items,$petugasId,$s->id_servis,$s->kode_servis); $tx=new Transaksi(); $tx->forceFill(['kode_transaksi'=>$txCode,'id_pelanggan'=>$s->id_pelanggan,'id_petugas'=>$petugasId,'jenis_transaksi'=>'servis','tanggal'=>now(),'subtotal'=>$total,'diskon'=>0,'total'=>$total,'status'=>'belum_bayar','catatan'=>'Tagihan '.$s->kode_servis]); $tx->save(); $s->forceFill(['biaya_jasa'=>$jasa,'biaya_sparepart'=>$spare,'total_biaya'=>$total,'id_transaksi'=>$tx->id_transaksi,'status'=>'selesai','tanggal_selesai'=>$s->tanggal_selesai ?? now()])->save(); if($s->bookingServis?->id_promo){ try{ app(PromoEngineService::class)->applyToTransaction($tx,(int)$s->bookingServis->id_promo,'servis'); }catch(RuntimeException $e){} } app(ServiceExecutionService::class)->recordEvent($s->id_servis,'finalized','Tagihan diterbitkan untuk Finance / Kasir','petugas',$petugasId); return $tx->fresh(); }); }
}
